import path from "node:path";

export const shellGeneratedComment =
  "// Generated by scripts/generate-deployable-shells.mjs. Do not edit by hand.\n";
export const shellGeneratedFileMarker = `${shellGeneratedComment}\n`;

export const deployableShellConfig = {
  "catalog-admin": {
    fileParts: ["deployables", "catalog-admin", "app", "context-shell.generated.ts"],
    shellOwnerPackage: "@chase-sets/catalog",
    slots: new Set(["primary-nav"]),
  },
  "identity-admin": {
    fileParts: ["deployables", "identity-admin", "app", "context-shell.generated.ts"],
    shellOwnerPackage: "@chase-sets/identity",
    slots: new Set(["primary-nav"]),
  },
  marketplace: {
    fileParts: ["deployables", "marketplace", "app", "context-shell.generated.ts"],
    shellOwnerPackage: "@chase-sets/discovery",
    slots: new Set(["top-nav", "bottom-nav"]),
  },
};

function toPascalCase(value) {
  return value
    .split(/[^a-zA-Z0-9]+/)
    .filter(Boolean)
    .map((segment) => segment[0].toUpperCase() + segment.slice(1))
    .join("");
}

export function resolveDeployableShellPath(repoRoot, deployable) {
  const config = deployableShellConfig[deployable];
  if (!config) {
    throw new Error(`Unknown deployable shell config: ${deployable}`);
  }

  return path.join(repoRoot, ...config.fileParts);
}

function buildContributionLiteral(contribution) {
  const requiredPermissions =
    contribution.requiredPermissions.length === 0
      ? "[]"
      : `[${contribution.requiredPermissions.map((permission) => `"${permission}"`).join(", ")}]`;

  return `  {
    key: "${contribution.key}",
    label: "${contribution.label}",
    icon: "${contribution.icon}",
    href: "${contribution.href}",
    order: ${contribution.order},
    visibility: "${contribution.visibility}",
    requiredPermissions: ${requiredPermissions},
  },`;
}

function buildContributionArray(contributions) {
  if (contributions.length === 0) {
    return "[]";
  }

  return `[
${contributions.map(buildContributionLiteral).join("\n")}
]`;
}

export function buildShellFileContent(deployable, contributions) {
  const config = deployableShellConfig[deployable];
  if (!config) {
    throw new Error(`Unknown deployable shell config: ${deployable}`);
  }

  const imports = `import type { NavigationItem } from "@chase-sets/design-system";`;
  const slotDeclarations = [...config.slots]
    .sort()
    .map((slot) => {
      const contributionsForSlot = contributions.filter(
        (contribution) => contribution.slot === slot,
      );
      const constantName = `${toPascalCase(slot)}Contributions`;
      return `const ${constantName} = ${buildContributionArray(contributionsForSlot)} satisfies readonly ShellContribution[];`;
    })
    .join("\n\n");

  const slotResolvers = [...config.slots]
    .sort()
    .map((slot) => {
      const functionName = `create${toPascalCase(deployable)}${toPascalCase(slot)}Items`;
      const constantName = `${toPascalCase(slot)}Contributions`;
      return `export function ${functionName}(actor?: ShellActor): NavigationItem[] {
  return resolveShellItems(${constantName}, actor);
}`;
    })
    .join("\n\n");

  return `${shellGeneratedFileMarker}${imports}

type ShellActor = Readonly<{
  permissions?: readonly string[];
}> | null | undefined;

type ShellContribution = Readonly<{
  key: string;
  label: string;
  icon: NavigationItem["icon"];
  href: string;
  order: number;
  visibility: "always" | "signed-in" | "signed-out";
  requiredPermissions: readonly string[];
}>;

function hasRequiredPermissions(
  actor: ShellActor,
  requiredPermissions: readonly string[],
) {
  if (requiredPermissions.length === 0) {
    return true;
  }

  const grantedPermissions = actor?.permissions ?? [];
  return requiredPermissions.every((permission) => grantedPermissions.includes(permission));
}

function isVisibleForActor(
  actor: ShellActor,
  contribution: ShellContribution,
) {
  if (contribution.visibility === "signed-in" && !actor) {
    return false;
  }

  if (contribution.visibility === "signed-out" && actor) {
    return false;
  }

  return hasRequiredPermissions(actor, contribution.requiredPermissions);
}

function resolveShellItems(
  contributions: readonly ShellContribution[],
  actor?: ShellActor,
): NavigationItem[] {
  return [...contributions]
    .filter((contribution) => isVisibleForActor(actor, contribution))
    .sort((left, right) =>
      left.order === right.order
        ? left.label.localeCompare(right.label)
        : left.order - right.order,
    )
    .map(({ key, label, icon, href }) => ({
      key,
      label,
      icon,
      href,
    }));
}

${slotDeclarations}

${slotResolvers}
`;
}
